function sm4(key){
  const SBOX=[0xd6,0x90,0xe9,0xfe,0xcc,0xe1,0x3d,0xb7];
  function encrypt(block){ const out=new Uint8Array(16);
    for(let i=0;i<16;i++) out[i]=SBOX[block[i]%SBOX.length]^key[i%key.length]; return out; }
  function decrypt(block){ return encrypt(block); }
  return {encrypt,decrypt};
}
const c=sm4(crypto.getRandomValues(new Uint8Array(16)));
console.log(c.encrypt(new Uint8Array(16)).length);

